1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Circle · ae683f770</title>
8	  <style>
9	    *,
10	    *::before,
11	    *::after {
12	      margin: 0;
13	      padding: 0;
14	      box-sizing: border-box;
15	    }
16	
17	    :root {
18	      --bg-start: #f4f5f7;
19	      --bg-end: #dfe3ea;
20	      --circle-start: #6ea8fe;
21	      --circle-end: #1d4ed8;
22	    }
23	
24	    @media (prefers-color-scheme: dark) {
25	      :root {
26	        --bg-start: #1b1e24;
27	        --bg-end: #0b0d10;
28	        --circle-start: #60a5fa;
29	        --circle-end: #1e3a8a;
30	      }
31	    }
32	
33	    body {
34	      min-height: 100vh;
35	      display: flex;
36	      justify-content: center;
37	      align-items: center;
38	      background: radial-gradient(circle at 50% 35%, var(--bg-start), var(--bg-end));
39	      font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
40	    }
41	
42	    svg {
43	      width: min(80vw, 80vh, 400px);
44	      height: auto;
45	      display: block;
46	    }
47	
48	    .disc {
49	      filter: drop-shadow(0 8px 24px rgba(0, 0, 0, 0.25));
50	      transform-box: fill-box;
51	      transform-origin: center;
52	      animation: pulse 4s ease-in-out infinite;
53	    }
54	
55	    @keyframes pulse {
56	      0%, 100% { transform: scale(1); }
57	      50%      { transform: scale(0.96); }
58	    }
59	
60	    @media (prefers-reduced-motion: reduce) {
61	      .disc {
62	        animation: none;
63	      }
64	    }
65	
66	    #disc-fill .stop-start { stop-color: var(--circle-start); }
67	    #disc-fill .stop-end   { stop-color: var(--circle-end); }
68	  </style>
69	</head>
70	<body>
71	  <svg id="ae683f770" viewBox="0 0 400 400" role="img" aria-labelledby="title desc">
72	    <title id="title">Circle</title>
73	    <desc id="desc">A single filled circle centered on the canvas.</desc>
74	    <defs>
75	      <radialGradient id="disc-fill" cx="35%" cy="30%" r="80%">
76	        <stop class="stop-start" offset="0%"/>
77	        <stop class="stop-end" offset="100%"/>
78	      </radialGradient>
79	    </defs>
80	    <circle class="disc" cx="200" cy="200" r="190" fill="url(#disc-fill)"/>
81	  </svg>
82	</body>
83	</html>
